// 作者给出实际材料和完整半日工期；首格式无额外技能增长或维修熟练度账。
#include "naval_repair_authoring.hpp"
#include "resident/storage/common_codec.hpp"
#include "naval_json_guard.hpp"
namespace hanmo::resident {
Outcome<NavalRepairPolicy> decode_naval_repair_policy(const BoundaryValue& v){auto unique=validate_naval_json_unique_keys(v,"military_naval/repair_policy");if(!unique.ok)return {false,{},unique.error};try{const StableId p="military_naval/repair_policy";boundary::fields(v,{"profile","rules"},{"npc_plans"},p);NavalRepairPolicy out;out.profile=boundary::get_string(v,"profile",p);for(const auto& value:boundary::array(boundary::field(v,"rules",p),p+"/rules")){boundary::fields(value,{"id","hull_id","duration","integrity_gain","minimum_crew","afloat_integrity_limit","materials"},{},p);NavalRepairRule rule;rule.id=boundary::get_string(value,"id",p);rule.hull_id=boundary::get_string(value,"hull_id",p);rule.duration=boundary::get_int(value,"duration",p);rule.integrity_gain=boundary::get_int(value,"integrity_gain",p);rule.minimum_crew=boundary::get_int(value,"minimum_crew",p);rule.afloat_integrity_limit=boundary::get_int(value,"afloat_integrity_limit",p);for(const auto& material:boundary::array(boundary::field(value,"materials",p),p+"/materials")){boundary::fields(material,{"item_id","quantity"},{},p);rule.materials.emplace_back(boundary::get_string(material,"item_id",p),boundary::get_int(material,"quantity",p));}out.rules.push_back(std::move(rule));}if(const auto* plans=v.find("npc_plans"))for(const auto& row:boundary::array(*plans,p+"/npc_plans")){boundary::fields(row,{"actor_id","rule_id","repair_below"},{},p);out.npc_plans.push_back({boundary::get_string(row,"actor_id",p),boundary::get_string(row,"rule_id",p),boundary::get_int(row,"repair_below",p)});}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 工法收费独立于实物工期字段，旧Naval3作者没有本段时保持原准入。
Outcome<NavalRepairChargePolicy> decode_naval_repair_charge_policy(const BoundaryValue& v){auto unique=validate_naval_json_unique_keys(v,"military_naval/repair_charge_policy");if(!unique.ok)return {false,{},unique.error};try{const StableId p="military_naval/repair_charge_policy";boundary::fields(v,{"profile","services"},{},p);NavalRepairChargePolicy out;out.profile=boundary::get_string(v,"profile",p);for(const auto& row:boundary::array(boundary::field(v,"services",p),p+"/services")){boundary::fields(row,{"id","version","rule_id","berth_place_id","garrison_id","organization_id","wallet_id","fee"},{},p);out.services.push_back({boundary::get_string(row,"id",p),boundary::get_string(row,"version",p),boundary::get_string(row,"rule_id",p),boundary::get_string(row,"berth_place_id",p),boundary::get_string(row,"garrison_id",p),boundary::get_string(row,"organization_id",p),boundary::get_string(row,"wallet_id",p),boundary::get_int(row,"fee",p)});}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}

}
